export const evidence = (prompt, correct, explanation) => ({ prompt, correct, explanation });

const catalogueUrl = 'https://waecgh.org/home/wassce-school/';
const timetableUrl = 'https://waecgh.org/timetable/';
const chiefExaminers2023Url = 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf';
