const ghanaianLanguageUrl = 'https://nacca.gov.gh/wp-content/uploads/2023/06/GHANAIAN-LANGUAGE.pdf';
const performingArtsUrl = 'https://www.nacca.gov.gh/wp-content/uploads/2025/04/Performing-Arts-Curriculum.pdf';

const waecSources = (reportTitle, reportUrl = chiefExaminers2023Url) => [
  { publisher: 'West African Examinations Council, Ghana', title: 'WASSCE for School Candidates subject catalogue', url: catalogueUrl },
  { publisher: 'West African Examinations Council, Ghana', title: 'WASSCE timetable and paper listing', url: timetableUrl },
  { publisher: 'West African Examinations Council, Ghana', title: reportTitle, url: reportUrl },
];

const topic = (code, title, objective, checks) => ({ code, title, objective, checks });
const check = (prompt, correct) => evidence(prompt, correct, 'The stated answer applies the governing subject principle directly and distinguishes it from the other same-topic alternatives.');

