const languageSources = (title, url) => [...waecSources(title, url), { publisher: 'National Council for Curriculum and Assessment, Ghana', title: 'Ghanaian Language Curriculum', url: ghanaianLanguageUrl }];
const languageTopics = (prefix, languageName, orthographyChecks) => [
  topic(prefix + '-1', languageName + ' sounds and orthography', 'Apply language-specific sound, letter, tone and word-division conventions accurately.', orthographyChecks),
  topic(prefix + '-2', 'Vocabulary and word formation', 'Interpret vocabulary in context and recognise productive word-formation relationships.', [check('Why should vocabulary meaning be inferred from context?', 'Surrounding words and the situation narrow the intended sense'), check('What is a root in word formation?', 'The core form to which other meaningful elements may be attached'), check('Why are synonyms not always interchangeable?', 'Register, collocation and shade of meaning can differ'), check('What does an antonym express?', 'A meaning opposed to another word in the relevant context'), check('Why should an idiom be interpreted as a whole?', 'Its established meaning may not equal the literal sum of its words')]),
  topic(prefix + '-3', 'Grammar and sentence construction', 'Construct complete, coherent sentences and apply grammatical relationships in context.', [check('What must a complete statement communicate?', 'A grammatically connected idea that is meaningful in context'), check('Why must pronoun reference be clear?', 'The reader should identify the person or thing referred to'), check('What does conjunction do?', 'It links words, phrases or clauses in a meaningful relationship'), check('Why is agreement important?', 'Related sentence elements must match the grammatical pattern of the language'), check('What is ambiguity?', 'A form that permits more than one plausible interpretation')]),
  topic(prefix + '-4', 'Reading and comprehension', 'Read varied passages, retrieve evidence, infer meaning and summarise accurately.', [check('What supports a comprehension answer?', 'Relevant evidence and meaning from the passage'), check('What is an inference?', 'A conclusion drawn from clues rather than stated directly'), check('Why should an answer be expressed concisely?', 'It should address the question without unrelated copied material'), check('What is the main idea?', 'The central point developed by a passage or paragraph'), check('Why are reference words traced?', 'Their antecedents clarify how ideas connect')]),
  topic(prefix + '-5', 'Composition and functional writing', 'Plan and write coherent narrative, descriptive, argumentative and functional texts.', [check('What should a composition plan establish?', 'Purpose, audience, main points and logical order'), check('Why are paragraphs used?', 'They group related ideas and show progression'), check('What makes an argument persuasive?', 'A clear position supported by relevant reasons and examples'), check('Why must a letter suit its recipient?', 'Register, greeting, content and closing depend on relationship and purpose'), check('What should revision check?', 'Meaning, organisation, grammar, spelling and punctuation')]),
  topic(prefix + '-6', 'Translation and register', 'Transfer meaning faithfully and choose language suited to audience, purpose and situation.', [check('What is the first duty in translation?', 'Preserve the intended meaning of the source in natural target-language expression'), check('Why is word-for-word substitution often inadequate?', 'Languages organise idiom, grammar and context differently'), check('What is register?', 'Language choice associated with a situation, audience or field'), check('Why must names and cultural terms be handled carefully?', 'Unjustified substitution can change identity or meaning'), check('How is a translation checked?', 'Compare meaning, omissions, additions and naturalness against the source')]),
  topic(prefix + '-7', 'Oral literature and cultural expression', 'Interpret proverbs, folktales, songs and oral performance within their social contexts.', [check('What is a proverb?', 'A compact traditional expression of shared observation or counsel'), check('Why is context needed to explain a proverb?', 'Its application depends on the situation and intended lesson'), check('What is a folktale?', 'A community-transmitted narrative that may entertain and teach'), check('What does performance add to oral literature?', 'Voice, rhythm, gesture and audience interaction shape meaning'), check('Why should cultural practices be described precisely?', 'Specific evidence avoids distortion and unsupported generalisation')]),
  topic(prefix + '-8', 'Written literature and examination communication', 'Analyse literary choices and present well-organised, evidence-based responses.', [check('What is a theme?', 'A central idea explored through a literary work'), check('What is characterisation?', 'Methods used to reveal a character’s qualities and development'), check('What is imagery?', 'Language that evokes sensory or imaginative experience'), check('Why should a literature answer cite relevant incidents?', 'Evidence connects interpretation to the actual work'), check('What makes an examination response coherent?', 'A focused answer with ordered points, explanation and appropriate evidence')]),
];

